/* Chelsea DNA — royal blue night at the Bridge, lion gold */
.theme-chelsea {
  --bg: oklch(0.258 0.088 259.8);
  --surface: oklch(0.302 0.107 261.3);
  --surface-2: oklch(0.347 0.120 261.6);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.728 0.059 261.7);
  --accent: oklch(0.744 0.150 82.0);
  --accent-fg: oklch(0.258 0.088 259.8);
  --accent-2: oklch(0.489 0.140 251.9);
  --line: oklch(1 0 0 / 15%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.744 0.150 82.0);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Kanit", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-chelsea h1,
.theme-chelsea h2,
.theme-chelsea h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-chelsea { --font-ui: var(--font-display); }
.theme-chelsea h1, .theme-chelsea h2 { text-transform: uppercase; }
.theme-chelsea button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-chelsea { background-image: radial-gradient(ellipse at 50% -10%, oklch(0.5 0.13 255 / 40%), transparent 55%); }
.theme-chelsea h1 { font-weight: 700; }
.theme-chelsea h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
